   "sintesis": "Una jueza de Nueva York asesta nuevos reveses a las estrategias legales a Joaquín y sus familiares para evitar el juicio previsto para marzo de 2027 Al escurridizo Naasón Joaquín García, máximo jerarca de la centenaria iglesia mexicana La Luz del Mundo, se le agotan las estrategias legales y el tiempo antes de enfrentar un juicio a partir de marzo próximo en un tribunal federal de Manhattan, en Nueva York.",
