    "De realizarse, el proceso expondría los secretos del líder religioso, de su familia y de su congregación, mientras los fiscales federales y sus testigos intentarían demostrar que operaron una organización criminal involucrada en el tráfico sexual y la explotación infantil, prácticamente desde la fundación del culto."
